"""Geometric viewpoint transforms for depth images."""

from __future__ import annotations

import math

import torch


_EPS = 1e-6


def _rotation_matrix(yaw: float, pitch: float, roll: float, *, device, dtype):
    """Return camera-space XYZ rotation, with angles in degrees."""
    yaw, pitch, roll = (
        math.radians(float(yaw)),
        math.radians(float(pitch)),
        math.radians(float(roll)),
    )
    cy, sy = math.cos(yaw), math.sin(yaw)
    cp, sp = math.cos(pitch), math.sin(pitch)
    cr, sr = math.cos(roll), math.sin(roll)
    ry = torch.tensor(
        [[cy, 0.0, sy], [0.0, 1.0, 0.0], [-sy, 0.0, cy]],
        device=device,
        dtype=dtype,
    )
    rx = torch.tensor(
        [[1.0, 0.0, 0.0], [0.0, cp, -sp], [0.0, sp, cp]],
        device=device,
        dtype=dtype,
    )
    rz = torch.tensor(
        [[cr, -sr, 0.0], [sr, cr, 0.0], [0.0, 0.0, 1.0]],
        device=device,
        dtype=dtype,
    )
    return rz @ rx @ ry


def _camera_intrinsics(height: int, width: int, horizontal_fov: float, device, dtype):
    if not 1.0 < float(horizontal_fov) < 179.0:
        raise ValueError("水平视场角必须在 1 到 179 度之间")
    fx = width / (2.0 * math.tan(math.radians(float(horizontal_fov)) / 2.0))
    fy = fx
    cx = (width - 1.0) * 0.5
    cy = (height - 1.0) * 0.5
    return torch.tensor((fx, fy, cx, cy), device=device, dtype=dtype)


def _splat_depth(
    points: torch.Tensor,
    height: int,
    width: int,
    fx: torch.Tensor,
    fy: torch.Tensor,
    cx: torch.Tensor,
    cy: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Forward-project points and keep the nearest point per output pixel."""
    batch, count, _ = points.shape
    z = points[..., 2]
    valid = torch.isfinite(points).all(dim=-1) & (z > _EPS)
    u = torch.round(points[..., 0] / z * fx + cx).long()
    v = torch.round(points[..., 1] / z * fy + cy).long()
    valid &= (u >= 0) & (u < width) & (v >= 0) & (v < height)

    linear = (v * width + u).clamp(0, height * width - 1)
    offsets = torch.arange(batch, device=points.device).view(-1, 1) * (height * width)
    linear = linear + offsets
    flat_size = batch * height * width
    depth = torch.full((flat_size,), float("inf"), device=points.device, dtype=points.dtype)
    depth.scatter_reduce_(0, linear.reshape(-1), torch.where(valid, z, torch.full_like(z, float("inf"))).reshape(-1), reduce="amin", include_self=True)
    depth = depth.view(batch, height, width)
    mask = torch.isfinite(depth)
    depth = torch.where(mask, depth, torch.zeros_like(depth))
    return depth, mask.to(points.dtype)


def transform_depth(
    depth: torch.Tensor,
    yaw: float = 0.0,
    pitch: float = 0.0,
    roll: float = 0.0,
    horizontal_fov: float = 60.0,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Rotate a [B,H,W,C] depth image and return depth, valid mask, hole mask."""
    if not isinstance(depth, torch.Tensor) or depth.ndim != 4:
        raise TypeError("深度视角变换需要 [batch, height, width, channels] 张量")
    if depth.shape[-1] < 1:
        raise ValueError("深度图至少需要一个通道")
    batch, height, width, _ = depth.shape
    source = depth[..., :3].to(dtype=torch.float32).mean(dim=-1)
    device = source.device
    intrinsics = _camera_intrinsics(height, width, horizontal_fov, device, source.dtype)
    fx, fy, cx, cy = intrinsics

    yy, xx = torch.meshgrid(
        torch.arange(height, device=device, dtype=source.dtype),
        torch.arange(width, device=device, dtype=source.dtype),
        indexing="ij",
    )
    z = source
    valid = torch.isfinite(z) & (z > _EPS)
    x = (xx.unsqueeze(0) - cx) / fx * z
    y = (yy.unsqueeze(0) - cy) / fy * z
    points = torch.stack((x, y, z), dim=-1).reshape(batch, -1, 3)
    rotation = _rotation_matrix(yaw, pitch, roll, device=device, dtype=source.dtype)
    points = points @ rotation.T

    points = torch.where(valid.reshape(batch, -1, 1), points, torch.full_like(points, float("nan")))
    transformed, valid_mask = _splat_depth(points, height, width, fx, fy, cx, cy)
    valid_mask = valid_mask.unsqueeze(-1).repeat(1, 1, 1, 3)
    hole_mask = 1.0 - valid_mask
    transformed = transformed.unsqueeze(-1).repeat(1, 1, 1, 3)
    return transformed.to(dtype=depth.dtype), valid_mask.to(dtype=depth.dtype), hole_mask.to(dtype=depth.dtype)


class QQDepthViewTransform:
    """Rotate a depth map into a new camera view using geometric reprojection."""

    CATEGORY = "QQ/工具"
    FUNCTION = "transform"
    RETURN_TYPES = ("IMAGE", "IMAGE", "IMAGE")
    RETURN_NAMES = ("视角深度", "有效区域", "空洞区域")
    DESCRIPTION = "将深度图反投影为点云，旋转后重新投影；未观测到的区域输出为空洞 mask。"

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "depth": ("IMAGE",),
                "yaw": ("FLOAT", {"default": 0.0, "min": -90.0, "max": 90.0, "step": 1.0}),
                "pitch": ("FLOAT", {"default": 0.0, "min": -90.0, "max": 90.0, "step": 1.0}),
                "roll": ("FLOAT", {"default": 0.0, "min": -180.0, "max": 180.0, "step": 1.0}),
                "水平视场角": ("FLOAT", {"default": 60.0, "min": 1.0, "max": 179.0, "step": 1.0}),
            }
        }

    @staticmethod
    def transform(depth, yaw=0.0, pitch=0.0, roll=0.0, 水平视场角=60.0):
        return transform_depth(depth, yaw, pitch, roll, 水平视场角)


NODE_CLASS_MAPPINGS = {"QQDepthViewTransform": QQDepthViewTransform}
